public static void main(String[] args) {
    try (Scanner sc = new Scanner(System.in)) {
        number = sc.nextInt();

        stock = new int[number];
        food1 = new int[number];
        food2 = new int[number];

        for (int i = 0; i < number; i++) {
            stock[i] = sc.nextInt();
        }
        for (int i = 0; i < number; i++) {
            food1[i] = sc.nextInt();
        }
        for (int i = 0; i < number; i++) {
            food2[i] = sc.nextInt();
        }

        int maxServings = 0;

        for (int servingsA = 0; servingsA <= 1000000; servingsA++) {
            int maxB = Integer.MAX_VALUE;

            for (int i = 0; i < number; i++) {
                if (food1[i] * servingsA > stock[i]) {
                    maxB = -1;
                    break;
                }
                if (food2[i] > 0) {
                    maxB = Math.min(maxB, (stock[i] - servingsA * food1[i]) / food2[i]);
                }
            }

            if (maxB < 0) {
                break;
            }

            maxServings = Math.max(maxServings, servingsA + maxB);
        }

        System.out.println(maxServings);
    }
}

